question1="Comment protegez-vous les postes de travail ?"
question2="Comment securisez-vous l'acces Internet et le Wi-Fi ?"
question3="Comment votre entreprise prepare-t-elle ses collaborateurs a reconnaitre et reagir face aux cybermenaces ?"
question4="Comment protegez-vous les echanges et transactions electroniques (messagerie, partage de fichiers, paiements en ligne) ?"
question5="Comment protegez-vous les donnees critiques ?"


reponses1={1:"A. Aucune protection",2:"B. Antivirus uniquement",3:"C. Antivirus + pare-feu",4:"D. Protection complete"}
rec11=[{"recommandation":"Installer un antivirus assurant une protection contre les virus, vers, chevaux de Troie et autres logiciels malveillants","priorite":"Critique",'guide':"3.3.1 Vecteurs d'attaques cybercriminelles",'Justification (texte du guide CMRPI/AUSIM)':"Seule mesure de protection explicitement citée par le guide face aux malwares : « Installer un antivirus (logiciel qui protège un ordinateur contre les virus...) ». Son absence expose totalement le poste."},{"recommandation":"Configurer l'installation automatique des mises à jour de sécurité dès que possible","priorite":"Critique",'guide':"3.1.7 Politique de mise à jour des systèmes et logiciels",'Justification (texte du guide CMRPI/AUSIM)':"« Les attaquants exploitent ces vulnérabilités... longtemps après leur découverte et leur correction » : l'automatisation supprime le risque d'oubli d'un correctif critique."},{"recommandation":"Restreindre les droits d'installation et d'administration aux seuls utilisateurs autorisés","priorite":"Elevee",'guide':"3.1.5 Les permissions d'accès",'Justification (texte du guide CMRPI/AUSIM)':"« Il faut en principe éviter de donner le droit d'installation des programmes... aux utilisateurs non autorisés » — recommandation forte mais nuancée par « en principe »."},{"recommandation":"Interdire l'installation de logiciels non autorisés sur les postes de travail","priorite":"Elevee",'guide':"3.1.1 Sécurité du poste de travail",'Justification (texte du guide CMRPI/AUSIM)':"« Ne pas installer des logiciels sur le poste de travail » — règle de base énoncée simplement, sans qualificatif d'urgence absolue."}]
rec12=[{"recommandation":"Paramétrer un verrouillage automatique de l'écran pour qu'aucune session ne reste ouverte sans surveillance","priorite":"Elevee",'guide':"3.1.1 Sécurité du poste de travail",'Justification (texte du guide CMRPI/AUSIM)':"« Ne pas laisser le poste de travail accessible avec la session ouverte » — directive claire visant à limiter les accès non autorisés en l'absence de l'utilisateur."},{"recommandation":"Restreindre l'usage des outils système (éditeur de registre, invite de commandes) et n'autoriser que les applications nécessaires à l'activité","priorite":"Elevee",'guide':"3.1.5 Les permissions d'accès",'Justification (texte du guide CMRPI/AUSIM)':"« Vous pouvez minimiser les risques d'intrusions en interdisant l'exécution de l'Explorateur Windows, des commandes MS-DOS et des outils de la base de registre » — mesure technique conseillée."},{"recommandation":"Attribuer à chaque utilisateur un espace de travail avec des droits d'accès adaptés à son activité","priorite":"Elevee",'guide':"3.1.5 Les permissions d'accès",'Justification (texte du guide CMRPI/AUSIM)':"« Un simple utilisateur possède son répertoire de travail... et des répertoires plus restreints appropriés à son activité » — principe standard de moindre privilège."},{"recommandation":"Sensibiliser l'ensemble du personnel ayant accès à des informations sensibles à la confidentialité des données","priorite":"Critique",'guide':"3.4.3 Divulgation d'information",'Justification (texte du guide CMRPI/AUSIM)':"« Il est impératif de sensibiliser et d'impliquer le personnel... » — le guide emploie explicitement le terme « impératif »."},{"recommandation":"Interdire la copie sur le poste de travail de fichiers provenant de sources douteuses (clé USB, pièce jointe email, etc.)","priorite":"Critique",'guide':"3.1.2 Les virus, antivirus et firewall",'Justification (texte du guide CMRPI/AUSIM)':"« Ne jamais copier sur le poste de travail des fichiers provenant de sources douteuses » — le guide utilise « jamais », vecteur d'infection direct."}]
rec13=[{"recommandation":"Effectuer des sauvegardes régulières des documents importants","priorite":"Critique",'guide':"3.1.1 Sécurité du poste de travail",'Justification (texte du guide CMRPI/AUSIM)':"« Faire des sauvegardes régulières des documents importants » — mesure de base universellement critique face au risque de perte définitive de données."},{"recommandation":"Renouveler périodiquement les mots de passe des comptes utilisateurs (idéalement chaque mois)","priorite":"Elevee",'guide':"3.1.4 L'authentification des utilisateurs",'Justification (texte du guide CMRPI/AUSIM)':"« Le renouvellement périodique (mensuel si possible) du mot de passe » — présenté comme une consigne parmi d'autres, sans caractère absolu."},{"recommandation":"Interdire toute connexion avec un compte administrateur sur un poste non sécurisé","priorite":"Critique",'guide':"3.1.4 L'authentification des utilisateurs",'Justification (texte du guide CMRPI/AUSIM)':"« L'interdiction de se connecter avec des comptes administrateurs sur des postes non sécurisés » — le guide utilise le terme « interdiction »."}]
rec14=[{"recommandation":"Bloquer automatiquement le système après un nombre défini de tentatives de connexion infructueuses","priorite":"Elevee",'guide':"3.1.4 L'authentification des utilisateurs",'Justification (texte du guide CMRPI/AUSIM)':"« La déconnexion et le blocage du système après un certain nombre de tentatives de connexion » — consigne standard de sécurisation de l'authentification."},{"recommandation":"Protéger les fichiers contenant les mots de passe système (mécanisme shadow sous Unix, base de registre protégée sous Windows)","priorite":"Elevee",'guide':"3.1.5 Les permissions d'accès",'Justification (texte du guide CMRPI/AUSIM)':"Mesure technique détaillée par le guide (mécanisme shadow, poledit et regedit) présentée comme apportant « un niveau minimal de sécurité »."}]




reponses2={1:"A. Wi-Fi paramètres par défaut",2:"B. Wi-Fi protégé uniquement",3:"C. Wi-Fi + HTTPS",4:"D. Politique complète"}
rec21=[{"recommandation":"Ne jamais faire confiance à un réseau Wi-Fi public ne demandant aucun mot de passe","priorite":"Critique",'guide':"3.2.2 Sécurité des connexions Wi-Fi (LAN/WLAN)",'Justification (texte du guide CMRPI/AUSIM)':"« Ne faites jamais confiance aux réseaux de Wi-Fi public qui ne demandent pas de mots de passe » — formulation impérative absolue"},{"recommandation":"Désactiver la connexion automatique aux réseaux Wi-Fi inconnus","priorite":"Elevee",'guide':"3.2.2 Sécurité des connexions Wi-Fi (LAN/WLAN)",'Justification (texte du guide CMRPI/AUSIM)':"« Vérifiez si votre appareil est réglé pour se connecter automatiquement aux réseaux Wi-Fi inconnus. Si c'est le cas, désactivez cette fonction » — conseil pratique et concret."},{"recommandation":"Désactiver le Wi-Fi de l'appareil lorsqu'il n'est pas utilisé","priorite":"Moyenne",'guide':"3.2.2 Sécurité des connexions Wi-Fi (LAN/WLAN)",'Justification (texte du guide CMRPI/AUSIM)':"« Désactivez le Wi-Fi si vous ne l'utilisez pas. Cette mesure protégera vos données et vous aidera à économiser la batterie » — bénéfice présenté comme secondaire (confort + sécurité)."}]
rec22=[{"recommandation":"Maintenir à jour le serveur web, le système de gestion de contenu (CMS) et l'ensemble de ses extensions","priorite":"Critique",'guide':"3.2.3 Sécurité du site",'Justification (texte du guide CMRPI/AUSIM)':"« Avoir la dernière version est votre assurance pour être sécurisé contre l'ensemble des failles récentes » — condition nécessaire face aux failles connues et répertoriées."},{"recommandation":"Chiffrer la connexion au site web au moyen d'un certificat SSL (accès en HTTPS)","priorite":"Critique",'guide':"3.2.3 Sécurité du site",'Justification (texte du guide CMRPI/AUSIM)':"« Il faut les protéger mieux que tout le reste... une contrainte légale » : le chiffrement SSL répond à une obligation, pas seulement une bonne pratique."},{"recommandation":"Ne jamais désactiver l'antivirus ou le pare-feu de l'entreprise","priorite":"Critique",'guide':"3.2.1 Règles d'utilisation de l'internet",'Justification (texte du guide CMRPI/AUSIM)':"« N'enlevez ou ne désactivez jamais les mesures de protection mises en place... (comme l'antivirus ou le pare-feu) »."},{"recommandation":"Mettre en place une authentification HTTP en protection complémentaire du serveur web","priorite":"Moyenne",'guide':"3.2.3 Sécurité du site",'Justification (texte du guide CMRPI/AUSIM)':"« L'authentification http est l'une des protections possibles pour votre serveur web » — présentée comme une option parmi d'autres, non obligatoire."}]
rec23=[{"recommandation":"Utiliser un réseau privé virtuel (VPN) pour sécuriser les connexions à distance des collaborateurs nomades","priorite":"Elevee",'guide':"3.1.6 Sécurité de l'accès à distance / VPN",'Justification (texte du guide CMRPI/AUSIM)':"« Les VPN est une garantie de l'intégrité et la confidentialité des données échangées entre sites distants » — fortement recommandé pour tout accès nomade."},{"recommandation":"Protéger l'accès aux arborescences privées du site : seules les pages destinées au public doivent être visibles de l'extérieur","priorite":"Critique",'guide':"3.2.3 Sécurité du site",'Justification (texte du guide CMRPI/AUSIM)':"« L'accès aux arborescences privées de votre site doit être protégé » — formulation d'obligation."},{"recommandation":"Sauvegarder régulièrement le site web de l'entreprise","priorite":"Critique",'guide':"3.2.3 Sécurité du site",'Justification (texte du guide CMRPI/AUSIM)':"« Il est nécessaire de faire une sauvegarde régulière de votre site web. Ce backup aura une valeur inestimable si votre site web se fait attaquer »."}]
rec24=[{"recommandation":"Vérifier régulièrement que la version du site et du serveur correspond à la dernière version publiée par l'éditeur","priorite":"Elevee",'guide':"3.2.3 Sécurité du site",'Justification (texte du guide CMRPI/AUSIM)':"« N'hésitez pas à vérifier constamment la version de votre site web et du serveur vis-à-vis de la dernière version publiée »."},{"recommandation":"Étendre la politique de sécurité à l'ensemble du réseau, réseau local (LAN) et réseau externe (WAN) inclus","priorite":"Elevee",'guide':"3.1.3 Sécurité des serveurs",'Justification (texte du guide CMRPI/AUSIM)':"« La politique de sécurité doit englober l'ensemble du réseau informatique » — mesure stratégique et organisationnelle plus que technique immédiate."},{"recommandation":"Chiffrer les données sensibles avant leur stockage sur le serveur","priorite":"Critique",'guide':"3.2.3 Sécurité du site",'Justification (texte du guide CMRPI/AUSIM)':"« Toutes les informations doivent être cryptées avant d'être stockées pour une meilleure protection en cas de subtilisation des données »."}]

reponses3={1:"A. Jamais formés",2:"B. Sensibilisation occasionnelle",3:"C. Sensibilisés régulièrement",4:"D. Formations régulières"}
rec31=[{"recommandation":"Sensibiliser l'ensemble du personnel ayant accès à des informations sensibles à la valeur et à la confidentialité de ces données","priorite":"Critique",'guide':"3.4.3 Divulgation d'information",'Justification (texte du guide CMRPI/AUSIM)':"« Il est impératif de sensibiliser et d'impliquer le personnel... » (même justification que pour l'Axe 1)."},{"recommandation":"Apprendre aux collaborateurs à ne pas ouvrir de pièce jointe suspecte ou provenant d'un expéditeur inhabituel","priorite":"Critique",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« N'ouvrez pas les pièces jointes provenant de destinataires inconnus ou dont le titre ou le format paraissent incohérents » — vecteur d'infection majeur par email."}]
rec32=[{"recommandation":"Exiger le signalement immédiat de tout incident d'infection par un virus","priorite":"Critique",'guide':"3.1.2 Les virus, antivirus et firewall",'Justification (texte du guide CMRPI/AUSIM)':"« Signaler tout incident d'infection de virus » — directive de réaction rapide indispensable pour limiter la propagation."},{"recommandation":"Établir une liste des personnes habilitées à connaître certaines informations sensibles selon le poste occupé","priorite":"Moyenne",'guide':"3.4.3 Divulgation d'information",'Justification (texte du guide CMRPI/AUSIM)':"« Il est possible de créer dans l'entreprise une liste des personnes habilitées à connaître de telles informations » — mesure facultative selon le guide."}]
rec33=[{"recommandation":"Interdire formellement la divulgation d'informations personnelles ou professionnelles sur des forums ou réseaux sociaux","priorite":"Critique",'guide':"3.4.3 Divulgation d'information",'Justification (texte du guide CMRPI/AUSIM)':"« Il est important de ne jamais donner d'informations personnelles ou professionnelles sur des forums... ou réseaux sociaux »."},{"recommandation":"Former les collaborateurs à vérifier la cohérence entre l'expéditeur présumé d'un email et le contenu du message","priorite":"Elevee",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« Vérifiez la cohérence entre l'expéditeur présumé et le contenu du message et vérifiez son identité » — consigne standard de vigilance"}]
rec34=[{"recommandation":"Former les collaborateurs à ne jamais répondre à un spam ni cliquer sur ses liens ou pièces jointes","priorite":"Critique",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"Triple répétition du guide : « Ne jamais répondre à un spam... Ne jamais cliquer sur un lien html... Ne jamais cliquer sur la pièce jointe d'un spam »."},{"recommandation":"Former les collaborateurs à se méfier de tout lien reçu par email à caractère commercial suspect (tentative de phishing) et à le signaler à l'administrateur","priorite":"Critique",'guide':"3.2.1 Règles d'utilisation de l'internet",'Justification (texte du guide CMRPI/AUSIM)':"« Méfiez-vous. Les emails à consonance commerciale... sont souvent des tentatives de phishing. Supprimez l'email et contactez l'administrateur »."},{"recommandation":"Prévoir une procédure de réaction immédiate : déconnecter le poste infecté du réseau local","priorite":"Critique",'guide':"3.1.2 Les virus, antivirus et firewall",'Justification (texte du guide CMRPI/AUSIM)':"« En cas d'infection, déconnecter le poste de travail du réseau local » — mesure de confinement immédiat."}]

reponses4={1:"A. Aucune protection",2:"B. Antivirus mail",3:"C. Règles internes et accès contrôlés",4:"D. Mesures techniques et organisationnelles"} 
rec41=[{"recommandation":"Utiliser un logiciel antispam pour bloquer ou isoler les emails indésirables","priorite":"Moyenne",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« Utiliser un logiciel antispam pour bloquer ou déplacer les emails indésirables » — mesure de confort, sans qualificatif d'urgence dans le guide."},{"recommandation":"Vérifier la cohérence entre l'expéditeur présumé d'un email et le contenu du message avant toute action","priorite":"Elevee",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« L'identité d'un expéditeur n'étant en rien garantie : vérifiez la cohérence entre l'expéditeur présumé et le contenu du message »."},{"recommandation":"Ne pas ouvrir de pièce jointe suspecte ou provenant d'un expéditeur inconnu","priorite":"Critique",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"Même justification que pour l'Axe 3 : vecteur d'infection majeur, formulé de manière impérative dans le guide."},{"recommandation":"Créer des mots de passe d'au moins 8 caractères combinant majuscules, minuscules, chiffres et caractères spéciaux","priorite":"Critique",'guide':"3.4.2 Mot de passe",'Justification (texte du guide CMRPI/AUSIM)':"« Créez des mots de passe comptant au moins huit caractères... Créez un mot de passe fort en incluant [majuscules, minuscules, chiffres, caractères spéciaux] » — base de toute sécurité d'accès."}]
rec42=[{"recommandation":"Chiffrer les données pour limiter les risques d'interception et de surveillance des échanges","priorite":"Elevee",'guide':"3.1.4 L'authentification des utilisateurs",'Justification (texte du guide CMRPI/AUSIM)':"« Le cryptage des données pour rendre l'interception et la surveillance moins efficaces » — consigne parmi les règles d'authentification."},{"recommandation":"Centraliser le stockage et la gestion des fichiers via un système Web sécurisé, accessible en tout lieu","priorite":"Elevee",'guide':"3.4.4 Envois, réceptions et partage sécurisés",'Justification (texte du guide CMRPI/AUSIM)':"« Centraliser le stockage et la gestion des fichiers avec un système Web sécurisé, accessible en tout lieu... pour la protection hors site des données »."},{"recommandation":"Mettre en place des contrôles d'accès distincts pour séparer les fichiers privés des fichiers de production","priorite":"Elevee",'guide':"3.4.4 Envois, réceptions et partage sécurisés",'Justification (texte du guide CMRPI/AUSIM)':"« Mettre en place des contrôles et des autorisations d'accès pour sécuriser les fichiers privés et les séparer des fichiers de production »."},{"recommandation":"Adopter une politique de renouvellement des mots de passe tous les trois mois","priorite":"Elevee",'guide':"3.4.2 Mot de passe",'Justification (texte du guide CMRPI/AUSIM)':"« Votre entreprise devrait exiger ce changement tous les trois mois » — recommandation ferme mais conditionnelle (« devrait »)."}]
rec43=[{"recommandation":"Surveiller et documenter les modalités de partage des fichiers de l'entreprise","priorite":"Moyenne",'guide':"3.4.4 Envois, réceptions et partage sécurisés",'Justification (texte du guide CMRPI/AUSIM)':"« Surveiller les modalités de partage des fichiers de l'entreprise » — mesure de suivi, sans qualificatif d'urgence."},{"recommandation":"Optimiser la configuration de l'antivirus pour la messagerie électronique","priorite":"Moyenne",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« Optimiser la configuration de son antivirus vis-à-vis de la messagerie électronique » — amélioration continue, non impérative."},{"recommandation":"Vérifier la présence d'un cadenas et du protocole HTTPS dans la barre d'adresse avant tout paiement en ligne","priorite":"Elevee",'guide':"3.3.4 Escroquerie sur les moyens de paiement",'Justification (texte du guide CMRPI/AUSIM)':"« Contrôlez la présence d'un cadenas dans la barre d'adresse... Assurez-vous que la mention [https] apparaît au début de l'adresse » — vérification systématique recommandée"},{"recommandation":"Ne jamais transmettre le code confidentiel de la carte bancaire, y compris par téléphone ou par email","priorite":"Critique",'guide':"3.3.4 Escroquerie sur les moyens de paiement",'Justification (texte du guide CMRPI/AUSIM)':"« De manière générale, ne transmettez jamais le code confidentiel de votre carte bancaire »."}]
rec44=[{"recommandation":"Bloquer l'affichage des images et contenus externes dans les emails au format HTML","priorite":"Moyenne",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« Bloquer images et contenus externes dans les messages HTML » — mesure technique complémentaire, non prioritaire dans le guide."},{"recommandation":"Désactiver l'ouverture automatique des documents téléchargés et lancer une analyse antivirus avant toute ouverture","priorite":"Elevee",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« Désactivez l'ouverture automatique des documents téléchargés et lancez une analyse antivirus avant de les ouvrir »."},{"recommandation":"Configurer les logiciels et le navigateur pour qu'ils ne mémorisent pas les mots de passe saisis","priorite":"Moyenne",'guide':"3.4.1 Menaces sur le courrier électronique",'Justification (texte du guide CMRPI/AUSIM)':"« Configurez les logiciels, y compris votre navigateur web, pour qu'ils ne se 'souviennent' pas des mots de passe choisis » — mesure d'hygiène numérique."},{"recommandation":"Envisager l'usage d'un gestionnaire de mots de passe pour renforcer la robustesse et l'unicité des mots de passe utilisés","priorite":"Moyenne",'guide':"3.4.2 Mot de passe",'Justification (texte du guide CMRPI/AUSIM)':"« Vous pourriez aussi envisager l'utilisation d'un gestionnaire de mots de passe » — le guide emploie un conditionnel, mesure facultative."},{"recommandation":"Privilégier, pour les paiements en ligne, la confirmation de commande par un code envoyé par SMS","priorite":"Moyenne",'guide':"3.3.4 Escroquerie sur les moyens de paiement",'Justification (texte du guide CMRPI/AUSIM)':"« Privilégiez la méthode impliquant l'envoi d'un code de confirmation de la commande par SMS » — recommandation, non une obligation"}]

reponses5={1:"A. Aucune sauvegarde",2:"B. Sauvegardes manuelles",3:"C. Sauvegardes automatiques",4:"D. Sauvegardes + chiffrement"}
rec51=[{"recommandation":"Effectuer des sauvegardes régulières des données, quotidiennes ou hebdomadaires selon leur criticité","priorite":"Critique",'guide':"3.5.1 Stockage, sauvegarde et restauration des données",'Justification (texte du guide CMRPI/AUSIM)':"« Il est vivement conseillé d'effectuer des sauvegardes régulières (quotidiennes ou hebdomadaires) » — criticité renforcée par l'enjeu de perte définitive de données."},{"recommandation":"Veiller à la sécurité des fichiers contenant des données personnelles","priorite":"Critique",'guide':"3.5.4 Collecte et tri des données personnelles",'Justification (texte du guide CMRPI/AUSIM)':"Fait partie des « six règles d'or » imposées par la loi 09-08 relative au traitement des données personnelles — obligation légale."},{"recommandation":"Fixer une durée de conservation raisonnable pour les données personnelles collectées","priorite":"Critique",'guide':"3.5.4 Collecte et tri des données personnelles",'Justification (texte du guide CMRPI/AUSIM)':"Idem — règle d'or de la loi 09-08, obligation légale de conservation limitée dans le temps."},{"recommandation":"Chiffrer les données sensibles avant toute copie vers un service cloud","priorite":"Critique",'guide':"3.5.2 Transfert des données et Cloud computing",'Justification (texte du guide CMRPI/AUSIM)':"« Veillez à la confidentialité des données en... les chiffrant à l'aide d'un logiciel de chiffrement avant de les copier dans le cloud »."}]
rec52=[{"recommandation":"Utiliser un support de sauvegarde externe dédié, conservé en dehors des locaux de l'entreprise","priorite":"Elevee",'guide':"3.5.1 Stockage, sauvegarde et restauration des données",'Justification (texte du guide CMRPI/AUSIM)':"« Un disque dur externe réservé exclusivement à cet usage... de préférence à l'extérieur de l'entreprise » pour éviter la perte simultanée de l'original et de la copie."},{"recommandation":"N'emporter en déplacement que du matériel dédié à la mission, contenant uniquement les données strictement nécessaires","priorite":"Elevee",'guide':"3.5.3 Sécurité des données de la PME vs Mobilité",'Justification (texte du guide CMRPI/AUSIM)':"« N'utilisez que du matériel... dédié à la mission, et ne contenant que les données nécessaires »."},{"recommandation":"Évaluer les risques (confidentialité, localisation, disponibilité, réversibilité contractuelle) avant toute sauvegarde sur une plateforme cloud","priorite":"Elevee",'guide':"3.5.2 Transfert des données et Cloud computing",'Justification (texte du guide CMRPI/AUSIM)':"« Soyez conscient que ces sites de stockage peuvent être la cible d'attaques informatiques et que ces solutions impliquent des risques spécifiques »."}]
rec53=[{"recommandation":"Accorder une attention particulière à la durée de vie des supports de sauvegarde utilisés","priorite":"Moyenne",'guide':"3.5.1 Stockage, sauvegarde et restauration des données",'Justification (texte du guide CMRPI/AUSIM)':"« Il est nécessaire d'accorder une attention particulière à la durée de vie de ces supports » — mesure de maintenance secondaire par rapport à la sauvegarde elle-même."},{"recommandation":"Recourir à des spécialistes techniques et juridiques pour la rédaction de contrats cloud personnalisés, adaptés aux enjeux de l'entreprise","priorite":"Moyenne",'guide':"3.5.2 Transfert des données et Cloud computing",'Justification (texte du guide CMRPI/AUSIM)':"« N'hésitez pas à recourir à des spécialistes techniques et juridiques pour la rédaction des contrats personnalisés » — suggestion facultative du guide."},{"recommandation":"Assurer la confidentialité des données personnelles en en limitant l'accès aux seules personnes autorisées","priorite":"Critique",'guide':"3.5.4 Collecte et tri des données personnelles",'Justification (texte du guide CMRPI/AUSIM)':"Règle d'or de la loi 09-08 — obligation légale de confidentialité des données personnelles."}]
rec54=[{"recommandation":"Lire attentivement les conditions générales d'utilisation avant de recourir à tout service cloud","priorite":"Elevee",'guide':"3.5.2 Transfert des données et Cloud computing",'Justification (texte du guide CMRPI/AUSIM)':"« Soyez vigilant en prenant connaissance des conditions générales d'utilisation de ces services »."},{"recommandation":"Définir un objectif précis et documenté pour chaque traitement de données personnelles réalisé","priorite":"Critique",'guide':"3.5.4 Collecte et tri des données personnelles",'Justification (texte du guide CMRPI/AUSIM)':"Dernière des « six règles d'or » de la loi 09-08 — obligation légale de finalité déterminée du traitement."}]

